"""S13 table generators â€” write the claimâ†’evidence skeleton's exact artifact paths.

Authority
---------
* ``research/lit/claims_evidence_skeleton.md`` fixes the binding artifact paths
  per claim C1â€“C7 (``results/text/tables/noise_floor.csv``, ``drift_metrics_{explainer}.csv``,
  ``rq1_*.csv``, ``rq2_*.csv``, ``rq3_*.csv``, ``rq4_*.csv``, ``cl_metrics.csv``,
  ``per_class_f1.{npz,csv}``) and requires every row to trace to a run manifest.
* ``docs/source_documents/Doc 2b`` Â§S13: tables are "generated by scripts from manifests,
  never hand-edited"; Â§S8â€“Â§S12 define each table's content.
* ``docs/05`` Â§8â€“Â§13: metric/statistics definitions (all delegated to the
  analysis modules â€” this layer only assembles/writes).

Design rules
------------
* One function per claim/table family; each takes already-loaded
  :mod:`pandas` frames / tensors and a :class:`analysis.artifacts.ArtifactLayout`,
  writes the CSV(s), and returns a dict of written paths. No global state, no
  hard-coded absolute paths, deterministic float formatting (``%.10g``) so a
  regenerated table is byte-identical for identical inputs.
* The synthetic demo passes ``ArtifactLayout(src/analysis/examples/results)``; real
  runs use the project ``results/`` root. Nothing here writes outside the given
  layout.
* Tables that carry an AI/statistics result also carry the provenance columns the
  verifier needs (n, CI lo/hi, seed, bootstrap resamples, caveat).
"""

from __future__ import annotations

from collections.abc import Mapping, Sequence
from pathlib import Path
from typing import Any

import numpy as np
import pandas as pd

from src.analysis import artifacts
from src.analysis import metrics_cl as mc
from src.analysis import noise_floor as nf
from src.analysis import rq3 as rq3mod
from src.analysis import stats as st

FLOAT_FORMAT = "%.10g"


class TableError(ValueError):
    """Raised when a table cannot be assembled from the given inputs."""


# ---------------------------------------------------------------------------
# Generic helpers
# ---------------------------------------------------------------------------
def write_table(frame: pd.DataFrame, path: str | Path) -> Path:
    """Deterministically write one CSV (no index, fixed float format)."""
    target = Path(path)
    target.parent.mkdir(parents=True, exist_ok=True)
    # stable column order; tolerate fully-empty frames by writing the header only
    frame = frame.copy()
    for column in frame.columns:
        if frame[column].dtype == object:
            frame[column] = frame[column].map(lambda value: "" if value is None else value)
    frame.to_csv(target, index=False, float_format=FLOAT_FORMAT, lineterminator="\n")
    return target


def _frame(rows: Sequence[Mapping[str, Any]], columns: Sequence[str]) -> pd.DataFrame:
    frame = pd.DataFrame(rows)
    for column in columns:
        if column not in frame.columns:
            frame[column] = np.nan
    return frame[list(columns)]


# ---------------------------------------------------------------------------
# S5 â€” CL metrics + per-class F1 tensor
# ---------------------------------------------------------------------------
#: Engineer S5 writer schema (D-043: ``src/scripts/run_eval.py`` is the single writer
#: of ``cl_metrics.csv``; the analysis generator reproduces that schema so the
#: synthetic demo exercises the same validators, and can be used as a cross-check).
CL_METRICS_COLUMNS: tuple[str, ...] = (
    "strategy",
    "model",
    "seed",
    "metric",
    "final_average_macro_f1",
    "forgetting",
    "bwt",
    "note",
)

#: Metric-row labels of the S5 writer (D-033 dual macro-F1).
CL_METRIC_ALL = "all_classes"
CL_METRIC_SUPPORTED = "supported_set"


def _s5_metrics_rows(
    tensor: mc.RMetricTensor,
    *,
    supported_classes: Sequence[str] = (),
) -> list[dict[str, Any]]:
    """D-033 dual CL metrics in the engineer S5 long format."""
    rows = [
        {
            "strategy": tensor.strategy,
            "model": tensor.model,
            "seed": "" if tensor.seed is None else int(tensor.seed),
            "metric": CL_METRIC_ALL,
            "final_average_macro_f1": tensor.final_macro_f1(),
            "forgetting": tensor.forgetting(),
            "bwt": tensor.bwt(),
            "note": "",
        }
    ]
    if supported_classes and tensor.R_class is not None:
        excluded = [name for name in tensor.classes if name not in supported_classes]
        supported_matrix = tensor.class_macro_matrix(exclude_classes=excluded)
        supported_tensor = mc.RMetricTensor(
            supported_matrix,
            strategy=tensor.strategy,
            model=tensor.model,
            seed=tensor.seed,
            n_periods=tensor.n_periods,
        )
        rows.append(
            {
                "strategy": tensor.strategy,
                "model": tensor.model,
                "seed": "" if tensor.seed is None else int(tensor.seed),
                "metric": CL_METRIC_SUPPORTED,
                "final_average_macro_f1": supported_tensor.final_macro_f1(),
                "forgetting": supported_tensor.forgetting(),
                "bwt": supported_tensor.bwt(),
                "note": "",
            }
        )
    return rows


def cl_metrics_frame(
    tensors: Mapping[Any, mc.RMetricTensor] | Sequence[mc.RMetricTensor],
    *,
    supported_classes: Sequence[str] = (),
) -> pd.DataFrame:
    """Rows in the engineer S5 ``cl_metrics.csv`` long format (D-043).

    Two rows per run (D-033 dual macro-F1): ``metric=all_classes`` and
    ``metric=supported_set`` (the latter only when supported classes are given and
    per-class values exist; exclusions are explicit, never a silent average).
    """
    values = (
        [tensors[key] for key in sorted(tensors, key=str)]
        if isinstance(tensors, Mapping)
        else tensors
    )
    rows: list[dict[str, Any]] = []
    for tensor in values:
        rows.extend(_s5_metrics_rows(tensor, supported_classes=supported_classes))
    return _frame(rows, CL_METRICS_COLUMNS)


def generate_cl_metrics(
    tensors: Mapping[Any, mc.RMetricTensor] | Sequence[mc.RMetricTensor],
    layout: artifacts.ArtifactLayout,
    *,
    supported_classes: Sequence[str] = (),
) -> Path:
    """``results/text/tables/cl_metrics.csv`` in the engineer S5 writer schema (D-043)."""
    frame = cl_metrics_frame(tensors, supported_classes=supported_classes)
    return write_table(frame, layout.table("cl_metrics"))


def generate_per_class_f1(
    tensors: Mapping[Any, mc.RMetricTensor] | Sequence[mc.RMetricTensor],
    layout: artifacts.ArtifactLayout,
    *,
    primary_key: tuple[str, str, int] | None = None,
) -> dict[str, Path]:
    """``per_class_f1.csv`` (all runs, long format) + ``per_class_f1.npz`` (primary run).

    The npz format is frozen by :mod:`analysis.metrics_cl`
    (:data:`analysis.metrics_cl.PER_CLASS_F1_NPZ_KEYS`); the CSV carries every
    run so no per-class result is lost when several strategies/models exist.
    """
    values = dict(tensors) if isinstance(tensors, Mapping) else {index: tensor for index, tensor in enumerate(tensors)}
    if not values:
        raise TableError("no tensors supplied for per_class_f1")
    rows: list[dict[str, Any]] = []
    for key in sorted(values, key=str):
        rows.extend(values[key].to_long_rows())
    frame = _frame(rows, mc.PER_CLASS_F1_CSV_COLUMNS)
    csv_path = write_table(frame, layout.table("per_class_f1_csv"))
    if primary_key is not None:
        if primary_key not in values:
            raise TableError(f"primary_key {primary_key!r} not among tensors {sorted(values, key=str)}")
        primary = values[primary_key]
    else:
        primary = values[sorted(values, key=str)[0]]
    npz_paths = mc.save_per_class_f1(primary, layout.table("per_class_f1_npz"))
    return {"per_class_f1_csv": csv_path, "per_class_f1_npz": npz_paths[0]}


def write_s5_writer_artifacts(
    tensors: Mapping[Any, mc.RMetricTensor] | Sequence[mc.RMetricTensor],
    layout: artifacts.ArtifactLayout,
    *,
    primary_key: tuple[str, str, int] | None = None,
    supported_classes: Sequence[str] = (),
    dataset: str = "NF-UNSW-NB15-v3",
) -> dict[str, Path]:
    """Reproduce the engineer S5 writer artifacts (D-043) from a tensor.

    Emits ``cl_matrix.json``, ``cl_per_class_f1.json`` and ``cl_metrics.csv`` in
    the exact schema of ``src/scripts/run_eval.py`` (continuous-learning evaluation
    writer). The real pipeline uses the engineer's writer; this function exists so
    (a) the synthetic demo exercises the same validators and cross-check and
    (b) the verifier can regenerate the writer format from the analysis tensor for
    comparison. The synthetic demo's ``class_counts`` are placeholders (the demo
    has no raw labels) and are clearly banner-marked as synthetic.
    """
    import json
    from datetime import datetime, timezone

    if isinstance(tensors, mc.RMetricTensor):
        values = {"single": tensors}
    elif isinstance(tensors, Mapping):
        values = dict(tensors)
    else:
        values = {index: tensor for index, tensor in enumerate(tensors)}
    if not values:
        raise TableError("no tensors supplied for write_s5_writer_artifacts")
    primary = values[primary_key] if primary_key is not None else values[sorted(values, key=str)[0]]
    if primary_key is not None and primary_key not in values:
        raise TableError(f"primary_key {primary_key!r} not among tensors {sorted(values, key=str)}")
    n = primary.n_periods
    class_order = list(primary.classes)

    def _cell(i: int, j: int) -> dict[str, Any] | None:
        macro = primary.R[i, j]
        if not np.isfinite(macro):
            return None
        per_class: dict[str, float] = {}
        if primary.R_class is not None:
            for index, name in enumerate(primary.classes):
                value = primary.R_class[i, j, index]
                per_class[str(index)] = float(value) if np.isfinite(value) else 0.0
        else:  # pragma: no cover - tensor without per-class values
            per_class = {str(index): float("nan") for index in range(len(class_order))}
        supported_ids = [index for index, name in enumerate(primary.classes) if name in set(supported_classes)]
        supported_values = [per_class[str(index)] for index in supported_ids if np.isfinite(per_class[str(index)])]
        supported_macro = float(np.mean(supported_values)) if supported_values else float("nan")
        # Placeholder counts: sum equals n_edges by construction (synthetic demo only).
        class_counts = {str(index): 1 for index in range(len(class_order))}
        return {
            "dual_macro_f1": {
                "macro_f1_all_classes": float(macro),
                "macro_f1_supported_set": supported_macro,
                "n_classes_all": len(class_order),
                "n_classes_supported": len(supported_ids),
                "supported_set_labels": supported_ids,
                "class_counts": class_counts,
                "n_edges": len(class_order),
            },
            "per_class_f1": per_class,
        }

    dual_cells: dict[str, Any] = {}
    for i in range(n):
        row_cells: dict[str, Any] = {}
        for j in range(n):
            cell = _cell(i, j)
            if cell is not None:
                row_cells[str(j + 1)] = cell
        if row_cells:
            dual_cells[str(i + 1)] = row_cells
    supported_matrix = (
        primary.class_macro_matrix(exclude_classes=[name for name in primary.classes if name not in set(supported_classes)])
        if supported_classes and primary.R_class is not None
        else primary.R
    )
    complete = np.all(np.isfinite(primary.R[-1, :])) and len(dual_cells) == n
    payload = {
        "schema_version": 1,
        "generated_at_utc": datetime.now(timezone.utc).isoformat(timespec="seconds"),
        "dataset": dataset,
        "strategy": primary.strategy,
        "model": primary.model,
        "seed": primary.seed,
        "class_order": class_order,
        "supported_set": list(supported_classes),
        "checkpoints": {
            str(period + 1): {
                "path": f"synthetic://M_{period + 1}.pt",
                "seed": primary.seed,
                "period": period + 1,
                "sha256": f"synthetic-{primary.strategy}-{primary.model}-{period + 1}",
            }
            for period in range(n)
        },
        "rows": {str(index + 1): f"M_{index + 1}" for index in range(n)},
        "columns": {str(index + 1): f"period_{index + 1}" for index in range(n)},
        "matrix": {
            "all_classes": np.where(np.isfinite(primary.R), primary.R, np.nan).tolist(),
            "supported_set": np.where(np.isfinite(supported_matrix), supported_matrix, np.nan).tolist(),
        },
        "dual_macro_f1_per_cell": dual_cells,
        "note": "" if complete else "last checkpoint row incomplete; CL metrics not computed yet",
    }
    matrix_path = layout.table("cl_matrix_json") if "cl_matrix_json" in artifacts.TABLE_ARTIFACTS else None
    # The S5 writer artifacts are not (yet) in the analysis path registry: they are
    # engineer-owned per D-043. In the real results root the engineer writes them;
    # the synthetic demo writes them next to the demo tables.
    tables_root = layout.tables_root
    matrix_target = tables_root / "cl_matrix.json"
    per_class_target = tables_root / "cl_per_class_f1.json"
    tables_root.mkdir(parents=True, exist_ok=True)
    matrix_target.write_text(json.dumps(payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    per_class_payload = {"per_class_f1": dual_cells, "class_order": class_order}
    per_class_target.write_text(json.dumps(per_class_payload, indent=2, sort_keys=True) + "\n", encoding="utf-8")
    metrics_frame = cl_metrics_frame([primary], supported_classes=supported_classes)
    if not complete:
        metrics_frame["note"] = "incomplete_matrix"
    metrics_path = write_table(metrics_frame, tables_root / "cl_metrics.csv")
    return {"cl_matrix_json": matrix_target, "cl_per_class_json": per_class_target, "cl_metrics_csv": metrics_path}


# ---------------------------------------------------------------------------
# S8 â€” noise floor + drift metrics
# ---------------------------------------------------------------------------
def noise_floor_thresholds(
    noise_frames: Mapping[str, pd.DataFrame],
    *,
    cfg: nf.NoiseFloorConfig | None = None,
    extra_group_columns: Sequence[str] = ("explainer",),
) -> dict[str, nf.ThresholdTable]:
    """Per-channel :class:`ThresholdTable` from the S8 noise frames."""
    if not noise_frames:
        raise TableError("noise_floor_thresholds needs at least one channel frame")
    thresholds: dict[str, nf.ThresholdTable] = {}
    for channel, frame in noise_frames.items():
        if frame is None or len(frame) == 0:
            continue
        thresholds[channel] = nf.per_class_thresholds(
            frame,
            value_column="drift_primary",
            class_column="class",
            extra_group_columns=extra_group_columns,
            cfg=cfg,
            channel=channel,
        )
    if not thresholds:
        raise TableError("every noise channel frame was empty")
    return thresholds


def noise_floor_frame(
    noise_frames: Mapping[str, pd.DataFrame],
    thresholds: Mapping[str, nf.ThresholdTable],
    *,
    cfg: nf.NoiseFloorConfig | None = None,
) -> pd.DataFrame:
    """Rows for ``results/text/tables/noise_floor.csv`` (S8 output, all channels)."""
    config = cfg or nf.NoiseFloorConfig()
    frames: list[pd.DataFrame] = []
    for channel, frame in noise_frames.items():
        if frame is None or len(frame) == 0:
            continue
        table = thresholds.get(channel)
        rows = nf.noise_floor_rows(
            frame,
            thresholds={channel: table} if table is not None else None,
            value_column="drift_primary",
            class_column="class",
            config=config,
        )
        rows["channel"] = channel
        frames.append(rows)
    if not frames:
        raise TableError("no non-empty noise channel frames supplied")
    combined = pd.concat(frames, ignore_index=True, sort=False)
    first_columns = ["channel", "model", "explainer", "class", "n_null_pairs", "quantile", "mean", "median", "q95", "threshold_source", "threshold_n", "global_q95"]
    for column in first_columns:
        if column not in combined.columns:
            combined[column] = np.nan
    remaining = [column for column in combined.columns if column not in first_columns]
    return combined[first_columns + remaining]


def generate_noise_floor(
    noise_frames: Mapping[str, pd.DataFrame],
    layout: artifacts.ArtifactLayout,
    *,
    cfg: nf.NoiseFloorConfig | None = None,
    extra_group_columns: Sequence[str] = ("explainer",),
) -> dict[str, Any]:
    """Write ``results/text/tables/noise_floor.csv`` and return the threshold tables."""
    thresholds = noise_floor_thresholds(noise_frames, cfg=cfg, extra_group_columns=extra_group_columns)
    frame = noise_floor_frame(noise_frames, thresholds, cfg=cfg)
    path = write_table(frame, layout.table("noise_floor"))
    return {"path": path, "frame": frame, "thresholds": thresholds}


def generate_drift_metrics(
    real_drift: pd.DataFrame,
    layout: artifacts.ArtifactLayout,
) -> dict[str, Path]:
    """``results/text/tables/drift_metrics_{explainer}.csv`` for every explainer present (S8)."""
    if "explainer" not in real_drift.columns:
        raise TableError("real_drift frame lacks an 'explainer' column")
    paths: dict[str, Path] = {}
    for explainer in real_drift["explainer"].dropna().unique():
        subset = real_drift[real_drift["explainer"] == explainer].reset_index(drop=True)
        if subset.empty:
            continue
        canonical = artifacts.canonical_explainer(str(explainer))
        paths[canonical] = write_table(subset, layout.drift_metrics(canonical))
    if not paths:
        raise TableError("no explainer drift rows to write")
    return paths


# ---------------------------------------------------------------------------
# S9 â€” RQ1 (raw / null / excess, H1 tests, strategy comparison)
# ---------------------------------------------------------------------------
RQ1_ANCHOR_COLUMNS: tuple[str, ...] = (
    "strategy",
    "model",
    "explainer",
    "seed",
    "anchor_id",
    "class",
    "anchor_period",
    "checkpoint_j",
    "checkpoint_t",
    "drift_primary",
    "drift_null_mean",
    "null_mean",
    "null_median",
    "null_sd",
    "n_null",
    "floor_q95",
    "threshold_source",
    "excess",
    "above_floor",
    "channel",
    "quantile",
)


def build_rq1_tables(
    real_drift: pd.DataFrame,
    model_null_noise: pd.DataFrame,
    thresholds: nf.ThresholdTable | None = None,
    *,
    cfg: nf.NoiseFloorConfig | None = None,
    join_keys: Sequence[str] = ("model", "explainer", "anchor_id", "class"),
) -> dict[str, pd.DataFrame]:
    """Assemble every RQ1 table (claim C1/C2, Doc 2b Â§S9).

    Returns ``anchor_level`` (per anchor x update), ``aggregated`` (per
    strategy x model x explainer x class x period pair), ``h1_tests`` (per
    strategy x model x explainer configuration, Holm-adjusted) and
    ``strategy_comparison`` (paired replay/EWC âˆ’ FT differences).
    """
    config = cfg or nf.NoiseFloorConfig()
    if thresholds is None:
        thresholds = nf.per_class_thresholds(
            model_null_noise,
            value_column="drift_primary",
            class_column="class",
            extra_group_columns=("explainer",),
            cfg=config,
            channel=nf.MODEL_NULL,
        )
    if thresholds.channel != nf.MODEL_NULL:
        raise TableError(
            f"RQ1 must use the {nf.MODEL_NULL!r} floor (C1 wording); got channel {thresholds.channel!r}"
        )
    excess = nf.compute_excess(
        real_drift,
        model_null_noise,
        thresholds,
        join_keys=join_keys,
        value_column="drift_primary",
        class_column="class",
        cfg=config,
    )
    anchor_columns = [column for column in RQ1_ANCHOR_COLUMNS if column in excess.columns]
    extra_columns = [
        column
        for column in excess.columns
        if column.startswith("drift_") and column not in anchor_columns
    ]
    anchor_level = excess[anchor_columns + extra_columns].copy()
    aggregated = nf.aggregate_drift(excess, cfg=config)
    h1_tests = nf.h1_test(excess, cfg=config)
    comparisons = nf.strategy_comparison(excess, cfg=config)
    return {
        "anchor_level": anchor_level,
        "aggregated": aggregated,
        "h1_tests": h1_tests,
        "strategy_comparison": comparisons,
        "excess": excess,
    }


def generate_rq1(
    real_drift: pd.DataFrame,
    model_null_noise: pd.DataFrame,
    layout: artifacts.ArtifactLayout,
    *,
    thresholds: nf.ThresholdTable | None = None,
    cfg: nf.NoiseFloorConfig | None = None,
    join_keys: Sequence[str] | None = None,
) -> dict[str, Any]:
    """Write the four ``results/text/tables/rq1_*.csv`` artifacts (skeleton C1/C2).

    ``join_keys`` may omit ``model`` when the documented noise reference floor is
    shared across strategy families/models (T49 full-S7 reference-null contract).
    """
    kwargs = {} if join_keys is None else {"join_keys": tuple(join_keys)}
    tables = build_rq1_tables(real_drift, model_null_noise, thresholds, cfg=cfg, **kwargs)
    paths = {
        "anchor_level": write_table(tables["anchor_level"], layout.table("rq1_anchor_level")),
        "aggregated": write_table(tables["aggregated"], layout.table("rq1_aggregated")),
        "h1_tests": write_table(tables["h1_tests"], layout.table("rq1_h1_tests")),
        "strategy_comparison": write_table(tables["strategy_comparison"], layout.table("rq1_strategy_comparison")),
    }
    return {"paths": paths, **tables}


# ---------------------------------------------------------------------------
# S10 â€” RQ2 (neighbourhood change vs excess drift)
# ---------------------------------------------------------------------------
RQ2_ANCHOR_COLUMNS: tuple[str, ...] = (
    "strategy",
    "model",
    "explainer",
    "seed",
    "anchor_id",
    "class",
    "checkpoint_j",
    "checkpoint_t",
    "drift_primary",
    "null_mean",
    "excess",
    "above_floor",
    "neighbourhood_change",
    "degree",
)


def build_rq2_anchor_level(
    excess_frame: pd.DataFrame,
    neighbourhood: pd.DataFrame,
    *,
    pair_keys: Sequence[str] = ("strategy", "model", "explainer", "seed", "anchor_id", "class", "checkpoint_j", "checkpoint_t"),
) -> pd.DataFrame:
    """Merge per-anchor excess drift with the S10 neighbourhood-change score."""
    keys = [key for key in pair_keys if key in excess_frame.columns and key in neighbourhood.columns]
    if not keys:
        raise TableError("excess frame and neighbourhood frame share no pairing keys")
    change_column = None
    for candidate in ("neighbourhood_change", "mean_neighbourhood_change"):
        if candidate in neighbourhood.columns:
            change_column = candidate
            break
    if change_column is None:
        raise TableError("neighbourhood frame lacks a neighbourhood_change column")
    change_frame = neighbourhood[keys + [change_column]]
    if change_column != "neighbourhood_change":
        change_frame = change_frame.rename(columns={change_column: "neighbourhood_change"})
    if "degree" in neighbourhood.columns and "degree" not in change_frame.columns:
        change_frame["degree"] = neighbourhood["degree"].to_numpy()
    left_columns = [column for column in RQ2_ANCHOR_COLUMNS if column in excess_frame.columns]
    left = excess_frame[left_columns].copy()
    merged = left.merge(change_frame, on=keys, how="inner", validate="many_to_one")
    if merged.empty:
        raise TableError(f"neighbourhood merge produced no rows on keys {keys}")
    for column in RQ2_ANCHOR_COLUMNS:
        if column not in merged.columns:
            merged[column] = np.nan
    return merged[list(RQ2_ANCHOR_COLUMNS)]


def build_rq2_correlations(
    rq2_anchor_level: pd.DataFrame,
    *,
    group_columns: Sequence[str] = ("strategy", "model", "explainer", "checkpoint_j", "checkpoint_t"),
    value_column: str = "excess",
    change_column: str = "neighbourhood_change",
    class_column: str = "class",
    degree_column: str = "degree",
    cfg: nf.NoiseFloorConfig | None = None,
    permutation_n: int = 999,
) -> pd.DataFrame:
    """Spearman / partial-Spearman / permutation tests per update (Doc 2b Â§S10).

    Partial correlation controls for anchor class and anchor degree (Doc 2b Â§S10:
    "controlling for anchor class, anchor degree, and period pair" â€” the period
    pair is the group itself). ``channel`` labels real updates; a null-update
    comparison is added by the caller through the ``channel`` column.
    """
    config = cfg or nf.NoiseFloorConfig()
    for column in (*group_columns, value_column, change_column, class_column):
        if column not in rq2_anchor_level.columns:
            raise TableError(f"RQ2 anchor frame lacks column {column!r}")
    rows: list[dict[str, Any]] = []
    has_degree = degree_column in rq2_anchor_level.columns
    for key, group in rq2_anchor_level.groupby(list(group_columns), dropna=False, sort=True):
        key_values = key if isinstance(key, tuple) else (key,)
        frame = group.dropna(subset=[value_column, change_column, class_column]).copy()
        n = int(len(frame))
        if n < 3:
            continue
        x = frame[change_column].to_numpy(dtype=float)
        y = frame[value_column].to_numpy(dtype=float)
        class_codes = pd.factorize(frame[class_column].astype(str))[0].astype(float)
        controls = [class_codes]
        if has_degree:
            controls.append(frame[degree_column].to_numpy(dtype=float))
        control_matrix = np.column_stack(controls)
        spearman = st.spearman_correlation(x, y)
        interval = st.spearman_correlation_ci(x, y, n_resamples=config.n_resamples, alpha=config.alpha, seed=config.seed)
        partial = st.partial_spearman(x, y, control_matrix)
        partial_interval = st.partial_spearman_ci(
            x, y, control_matrix, n_resamples=config.n_resamples, alpha=config.alpha, seed=config.seed
        )
        permutation = st.permutation_test(x, y, alternative="greater", n_permutations=permutation_n, seed=config.seed)
        row: dict[str, Any] = dict(zip(group_columns, key_values))
        row.update(
            {
                "n_anchors": n,
                "channel": str(frame["channel"].iloc[0]) if "channel" in frame.columns else "real",
                "spearman": spearman,
                "spearman_ci_lo": interval.lo,
                "spearman_ci_hi": interval.hi,
                "partial_spearman": partial,
                "partial_ci_lo": partial_interval.lo,
                "partial_ci_hi": partial_interval.hi,
                "partial_controls": "class+degree" if has_degree else "class",
                "permutation_p_greater": permutation.p_value,
                "permutation_n": permutation_n,
                "bootstrap_resamples": config.n_resamples,
                "caveat": "association only; structural change is not labelled legitimate/harmful (docs/05 Â§10)",
            }
        )
        rows.append(row)
    frame_result = pd.DataFrame(rows)
    if frame_result.empty:
        raise TableError("RQ2 correlations produced no groups with enough anchors")
    frame_result["p_holm"] = st.holm_correction(frame_result["permutation_p_greater"].to_numpy(dtype=float))
    return frame_result


def generate_rq2(
    excess_frame: pd.DataFrame,
    neighbourhood: pd.DataFrame,
    layout: artifacts.ArtifactLayout,
    *,
    cfg: nf.NoiseFloorConfig | None = None,
) -> dict[str, Any]:
    """Write ``results/text/tables/rq2_anchor_level.csv`` and ``rq2_correlations.csv`` (C3)."""
    anchor_level = build_rq2_anchor_level(excess_frame, neighbourhood)
    correlations = build_rq2_correlations(anchor_level, cfg=cfg)
    paths = {
        "anchor_level": write_table(anchor_level, layout.table("rq2_anchor_level")),
        "correlations": write_table(correlations, layout.table("rq2_correlations")),
    }
    return {"paths": paths, "anchor_level": anchor_level, "correlations": correlations}


# ---------------------------------------------------------------------------
# S11 â€” RQ3 (drift feature table, forgetting labels, AUC, coefficients)
# ---------------------------------------------------------------------------
RQ3_AUC_COLUMNS: tuple[str, ...] = (
    "strategy",
    "cl_model",
    "explainer",
    "seed",
    "method",
    "role",
    "auc",
    "ci_lo",
    "ci_hi",
    "delta_auc",
    "delta_ci_lo",
    "delta_ci_hi",
    "p_value",
    "h3_supported",
    "n",
    "n_pos",
    "n_neg",
    "n_folds",
    "cv_group",
    "note",
    "caveat",
)


def build_rq3_tables(
    cl_tensors: Mapping[Any, mc.RMetricTensor] | Sequence[mc.RMetricTensor],
    excess_frame: pd.DataFrame,
    *,
    retention_frame: pd.DataFrame | None = None,
    rq2_anchor_level: pd.DataFrame | None = None,
    cfg: rq3mod.RQ3Config | None = None,
    explainer: str = "IG",
    skip_failed_runs: bool = True,
) -> dict[str, Any]:
    """Run the S11 analysis per CL run and assemble the RQ3 tables.

    Only the pre-registered primary explainer (IG feature attributions) is used
    for the drift features unless ``explainer`` says otherwise; labels come from
    :func:`analysis.rq3.build_forgetting_labels` (delta = 0.05, no post-hoc
    variants). Runs whose label/feature join is degenerate are skipped with an
    explicit note instead of producing a fabricated AUC.
    """
    config = cfg or rq3mod.RQ3Config(group_column="checkpoint_t")
    if "explainer" not in excess_frame.columns:
        raise TableError("excess frame lacks 'explainer'")
    canonical = artifacts.canonical_explainer(explainer)
    drift_subset = excess_frame[excess_frame["explainer"] == canonical].copy()
    if drift_subset.empty:
        raise TableError(f"no excess-drift rows for explainer {canonical!r}")
    if rq2_anchor_level is not None and "explainer" in rq2_anchor_level.columns:
        rq2_anchor_level = rq2_anchor_level[rq2_anchor_level["explainer"] == canonical]
    values = dict(cl_tensors) if isinstance(cl_tensors, Mapping) else {index: tensor for index, tensor in enumerate(cl_tensors)}
    feature_frames: list[pd.DataFrame] = []
    label_frames: list[pd.DataFrame] = []
    auc_frames: list[pd.DataFrame] = []
    coefficient_frames: list[pd.DataFrame] = []
    notes: list[str] = []
    for key in sorted(values, key=str):
        tensor = values[key]
        labels = rq3mod.build_forgetting_labels(tensor, delta=config.delta, horizon=config.horizon)
        labels = labels.rename(columns={"checkpoint": "checkpoint_t"})
        labels["cl_model"] = tensor.model
        run_drift = drift_subset[(drift_subset["strategy"] == tensor.strategy) & (drift_subset["model"] == tensor.model)]
        if run_drift.empty:
            notes.append(f"skipped {tensor.strategy}/{tensor.model}: no matching drift rows")
            continue
        try:
            features = rq3mod.build_rq3_features(
                labels,
                run_drift,
                retention_frame=retention_frame,
                rq2_frame=rq2_anchor_level,
                checkpoint_column="checkpoint_t",
                label_column=rq3mod.LABEL_COLUMN,
            )
            result = rq3mod.competing_baseline_analysis(features, cfg=config)
        except (rq3mod.RQ3Error, st.StatisticsError) as exc:
            if not skip_failed_runs:
                raise
            notes.append(f"skipped {tensor.strategy}/{tensor.model}: {exc}")
            continue
        run_id = {"strategy": tensor.strategy, "cl_model": tensor.model, "seed": tensor.seed if tensor.seed is not None else ""}
        feature_columns = {
            "anchor_count",
            "mean_excess_drift",
            "p90_excess_drift",
            "confidence_mean",
            "margin_mean",
            "retained_fraction",
            "mean_neighbourhood_change",
            "f1",
        }
        # Feature table only: future_* label metadata stays in rq3_forgetting_labels.csv
        # so no future information can be mistaken for a model feature (docs/05 Â§11).
        keep = [
            column
            for column in features.columns
            if column in feature_columns or column in {"class", "checkpoint_t", "eval_period", "label"}
        ]
        run_features = features[keep].copy()
        for column, value in run_id.items():
            run_features[column] = value
        feature_frames.append(run_features)
        labels_out = labels[
            [column for column in ("strategy", "cl_model", "seed", "checkpoint_t", "eval_period", "class", "f1", "future_checkpoint", "future_f1", "drop", "label", "delta", "horizon") if column in labels.columns]
        ].copy()
        label_frames.append(labels_out)
        auc_table = result.auc_table.copy()
        auc_table = auc_table.rename(columns={"model": "method"})
        auc_table["seed"] = run_id["seed"]
        auc_table["explainer"] = canonical
        auc_table["cv_group"] = result.group_column
        auc_table["caveat"] = "exploratory, T=5, association only (docs/05 Â§11)"
        for column, value in run_id.items():
            auc_table[column] = value
        delta_rows: list[dict[str, Any]] = []
        for _, delta in result.delta_auc_table.iterrows():
            delta_rows.append(
                {
                    "strategy": run_id["strategy"],
                    "cl_model": run_id["cl_model"],
                    "seed": run_id["seed"],
                    "explainer": canonical,
                    "method": f"delta:{delta['comparison']}",
                    "role": "delta",
                    "auc": float(delta["delta_auc"]),
                    "ci_lo": float(delta["ci_lo"]),
                    "ci_hi": float(delta["ci_hi"]),
                    "delta_auc": float(delta["delta_auc"]),
                    "delta_ci_lo": float(delta["ci_lo"]),
                    "delta_ci_hi": float(delta["ci_hi"]),
                    "p_value": float(delta["p_value"]),
                    "h3_supported": bool(delta["h3_supported"]),
                    "n": int(delta["n"]),
                    "n_pos": np.nan,
                    "n_neg": np.nan,
                    "n_folds": np.nan,
                    "cv_group": result.group_column,
                    "note": "drift_plus_baselines minus baselines_only" if delta["comparison"].startswith("drift_plus") else "drift_only minus baselines_only",
                    "caveat": "exploratory, T=5, association only (docs/05 Â§11)",
                }
            )
        auc_frames.append(pd.concat([auc_table, pd.DataFrame(delta_rows)], ignore_index=True, sort=False))
        coefficients = result.coefficient_table.copy()
        for column, value in run_id.items():
            coefficients[column] = value
        coefficients["explainer"] = canonical
        coefficient_frames.append(coefficients)
    if not auc_frames:
        raise TableError(f"no RQ3 run could be analysed; notes: {notes}")
    return {
        "features": pd.concat(feature_frames, ignore_index=True, sort=False) if feature_frames else pd.DataFrame(),
        "labels": pd.concat(label_frames, ignore_index=True, sort=False) if label_frames else pd.DataFrame(),
        "auc": pd.concat(auc_frames, ignore_index=True, sort=False),
        "coefficients": pd.concat(coefficient_frames, ignore_index=True, sort=False),
        "notes": notes,
    }


def generate_rq3(
    cl_tensors: Mapping[Any, mc.RMetricTensor] | Sequence[mc.RMetricTensor],
    excess_frame: pd.DataFrame,
    layout: artifacts.ArtifactLayout,
    *,
    retention_frame: pd.DataFrame | None = None,
    rq2_anchor_level: pd.DataFrame | None = None,
    cfg: rq3mod.RQ3Config | None = None,
    explainer: str = "IG",
) -> dict[str, Any]:
    """Write the four RQ3 artifacts (skeleton C4): features, labels, AUC, coefficients."""
    tables = build_rq3_tables(
        cl_tensors,
        excess_frame,
        retention_frame=retention_frame,
        rq2_anchor_level=rq2_anchor_level,
        cfg=cfg,
        explainer=explainer,
    )
    auc = tables["auc"].copy()
    for column in RQ3_AUC_COLUMNS:
        if column not in auc.columns:
            auc[column] = np.nan
    paths = {
        "features": write_table(tables["features"], layout.table("rq3_features")),
        "forgetting_labels": write_table(tables["labels"], layout.table("rq3_forgetting_labels")),
        "auc": write_table(auc[list(RQ3_AUC_COLUMNS)], layout.table("rq3_auc")),
        "coefficients": write_table(tables["coefficients"], layout.extra_table("rq3_coefficients")),
    }
    return {"paths": paths, **tables}


# ---------------------------------------------------------------------------
# S12 â€” RQ4 (EAR vs replay, ablations, H4 criterion)
# ---------------------------------------------------------------------------
RQ4_COMPARISON_COLUMNS: tuple[str, ...] = (
    "model",
    "variant",
    "seed",
    "drift_mean",
    "macro_f1",
    "forgetting",
    "bwt",
    "runtime_s",
    "row_kind",
    "drift_ci_lo",
    "drift_ci_hi",
    "macro_f1_ci_lo",
    "macro_f1_ci_hi",
    "drift_diff_vs_replay",
    "f1_diff_vs_replay",
    "h4_supported",
    "caveat",
)


def build_rq4_comparison(
    comparison: pd.DataFrame,
    *,
    cfg: nf.NoiseFloorConfig | None = None,
    baseline_variant: str = "replay",
) -> pd.DataFrame:
    """H4: paired drift/F1 differences vs plain replay + the pre-registered decision.

    H4 (docs/05 Â§12) = **lower drift than plain replay with at most one macro-F1
    point lost**. ``h4_supported`` is computed from the paired bootstrap CI lower
    bound of the drift difference being < 0 and the mean F1 difference >= -0.01;
    the decision is reported even when H4 fails.
    """
    config = cfg or nf.NoiseFloorConfig()
    required = {"model", "variant", "seed", "drift_mean", "macro_f1"}
    missing = required - set(comparison.columns)
    if missing:
        raise TableError(f"RQ4 comparison frame lacks columns {sorted(missing)}")
    raw = comparison.copy()
    raw["row_kind"] = "run"
    for column in RQ4_COMPARISON_COLUMNS:
        if column not in raw.columns:
            raw[column] = np.nan
    summary_rows: list[dict[str, Any]] = []
    for model, model_frame in comparison.groupby("model", sort=True):
        baseline = model_frame[model_frame["variant"] == baseline_variant]
        if baseline.empty:
            raise TableError(f"RQ4 baseline variant {baseline_variant!r} missing for model {model!r}")
        for variant in sorted(set(model_frame["variant"]) - {baseline_variant}):
            candidate = model_frame[model_frame["variant"] == variant]
            merged = candidate.merge(
                baseline,
                on="seed",
                suffixes=("_cmp", "_base"),
                how="inner",
                validate="one_to_one",
            )
            if merged.empty:
                raise TableError(f"no paired seeds between {variant!r} and {baseline_variant!r} for model {model!r}")
            drift_diff = st.paired_bootstrap_diff(
                merged["drift_mean_cmp"].to_numpy(dtype=float),
                merged["drift_mean_base"].to_numpy(dtype=float),
                n_resamples=config.n_resamples,
                alpha=config.alpha,
                seed=config.seed,
            )
            f1_diff = st.paired_bootstrap_diff(
                merged["macro_f1_cmp"].to_numpy(dtype=float),
                merged["macro_f1_base"].to_numpy(dtype=float),
                n_resamples=config.n_resamples,
                alpha=config.alpha,
                seed=config.seed,
            )
            effect = st.effect_size_summary(
                merged["drift_mean_cmp"].to_numpy(dtype=float),
                merged["drift_mean_base"].to_numpy(dtype=float),
                paired=True,
            )
            # Pre-registered H4 (docs/05 Â§12) on the point estimates: lower drift
            # AND at most one macro-F1 point lost; the CI consistency is recorded
            # separately so the decision cannot be quietly upgraded.
            h4 = bool(drift_diff.diff < 0.0 and f1_diff.diff >= -0.01)
            h4_ci_consistent = bool(drift_diff.hi < 0.0 and f1_diff.diff >= -0.01)
            summary_rows.append(
                {
                    "model": model,
                    "variant": variant,
                    "seed": "",
                    "drift_mean": float(np.mean(merged["drift_mean_cmp"])),
                    "macro_f1": float(np.mean(merged["macro_f1_cmp"])),
                    "forgetting": float(np.mean(merged["forgetting_cmp"])) if "forgetting_cmp" in merged.columns else np.nan,
                    "bwt": float(np.mean(merged["bwt_cmp"])) if "bwt_cmp" in merged.columns else np.nan,
                    "runtime_s": float(np.mean(merged["runtime_s_cmp"])) if "runtime_s_cmp" in merged.columns else np.nan,
                    "row_kind": f"h4_delta_vs_{baseline_variant}",
                    "drift_ci_lo": drift_diff.lo,
                    "drift_ci_hi": drift_diff.hi,
                    "macro_f1_ci_lo": f1_diff.lo,
                    "macro_f1_ci_hi": f1_diff.hi,
                    "drift_diff_vs_replay": drift_diff.diff,
                    "f1_diff_vs_replay": f1_diff.diff,
                    "h4_supported": h4,
                    "h4_ci_consistent": h4_ci_consistent,
                    "cohens_d_drift": effect["cohens_d"],
                    "n_pairs": int(merged.shape[0]),
                    "caveat": "H4 = lower drift AND at most 1 macro-F1 point lost (docs/05 Â§12); report failure honestly",
                }
            )
    summary = pd.DataFrame(summary_rows)
    combined = pd.concat([raw, summary], ignore_index=True, sort=False)
    for column in RQ4_COMPARISON_COLUMNS:
        if column not in combined.columns:
            combined[column] = np.nan
    extra = [column for column in combined.columns if column not in RQ4_COMPARISON_COLUMNS]
    return combined[list(RQ4_COMPARISON_COLUMNS) + extra]


def generate_rq4(
    comparison: pd.DataFrame,
    ablations: pd.DataFrame,
    layout: artifacts.ArtifactLayout,
    *,
    cfg: nf.NoiseFloorConfig | None = None,
) -> dict[str, Any]:
    """Write ``rq4_comparison.csv`` + ``rq4_ablations.csv`` (skeleton C5)."""
    comparison_frame = build_rq4_comparison(comparison, cfg=cfg)
    comparison_path = write_table(comparison_frame, layout.table("rq4_comparison"))
    ablation_path = write_table(ablations, layout.table("rq4_ablations"))
    return {"paths": {"comparison": comparison_path, "ablations": ablation_path}, "comparison": comparison_frame}


# ---------------------------------------------------------------------------
# Orchestration (synthetic demo; real runs call the generators with real frames)
# ---------------------------------------------------------------------------
def generate_all(
    *,
    cl_tensors: Mapping[Any, mc.RMetricTensor] | Sequence[mc.RMetricTensor],
    real_drift: pd.DataFrame,
    model_null_noise: pd.DataFrame,
    explainer_repeat_noise: pd.DataFrame | None,
    retention: pd.DataFrame | None,
    neighbourhood: pd.DataFrame,
    ear_comparison: pd.DataFrame,
    ear_ablations: pd.DataFrame,
    layout: artifacts.ArtifactLayout,
    supported_classes: Sequence[str] = (),
    cfg: nf.NoiseFloorConfig | None = None,
    partial: bool = False,
    real_drift_rq1: pd.DataFrame | None = None,
    rq1_join_keys: Sequence[str] | None = None,
    rq1_null_noise: pd.DataFrame | None = None,
) -> dict[str, Any]:
    """Generate every S13 table the skeleton claims, from assembled inputs.

    Order follows the dependency chain S5 â†’ S8 â†’ S9 â†’ S10 â†’ S11 â†’ S12; the S9
    excess frame feeds RQ2 and RQ3 so every downstream table is calibrated
    against the *same* noise floor (no recomputation drift).

    ``partial=True`` is the T49 single-group SMOKE wiring path: it writes the
    S5/S8/S9 contract (including RQ1) and stops before RQ2, whose correlation
    groups are defined for the full six-group matrix. Production calls keep the
    default ``partial=False`` and fail on missing groups.
    """
    config = cfg or nf.NoiseFloorConfig()
    layout.ensure()
    outputs: dict[str, Any] = {"paths": {}}
    outputs["paths"]["cl_metrics"] = generate_cl_metrics(cl_tensors, layout, supported_classes=supported_classes)
    outputs["paths"].update(generate_per_class_f1(cl_tensors, layout))
    # S5 writer-format artifacts (D-043) so validators/cross-check can run end-to-end
    # on the synthetic package exactly as they will on the real pipeline outputs.
    outputs["paths"].update(
        write_s5_writer_artifacts(
            cl_tensors,
            layout,
            supported_classes=supported_classes,
        )
    )
    # write_s5_writer_artifacts writes cl_metrics for the primary tensor only;
    # restore the all-run dual-metric table required by the six-group contract.
    outputs["paths"]["cl_metrics"] = generate_cl_metrics(
        cl_tensors, layout, supported_classes=supported_classes
    )

    noise_frames: dict[str, pd.DataFrame] = {nf.MODEL_NULL: model_null_noise}
    if explainer_repeat_noise is not None and len(explainer_repeat_noise) > 0:
        noise_frames[nf.EXPLAINER_REPEAT] = explainer_repeat_noise
    noise = generate_noise_floor(noise_frames, layout, cfg=config)
    outputs["noise_floor"] = noise["frame"]
    outputs["thresholds"] = noise["thresholds"]
    outputs["paths"]["noise_floor"] = noise["path"]
    outputs["paths"].update(
        {f"drift_metrics_{artifacts.explainer_slug(explainer)}": path for explainer, path in generate_drift_metrics(real_drift, layout).items()}
    )

    rq1 = generate_rq1(
        real_drift_rq1 if real_drift_rq1 is not None else real_drift,
        rq1_null_noise if rq1_null_noise is not None else model_null_noise,
        layout,
        thresholds=outputs["thresholds"].get(nf.MODEL_NULL),
        cfg=config,
        join_keys=rq1_join_keys,
    )
    outputs["paths"].update({f"rq1_{name}": path for name, path in rq1["paths"].items()})
    outputs["rq1"] = rq1
    if partial:
        outputs["partial_analysis"] = {
            "status": "s5_s8_s9_only",
            "note": "T49 single-group SMOKE wiring; RQ2-RQ4 require the full six-group matrix",
        }
        return outputs

    rq2 = generate_rq2(rq1["excess"], neighbourhood, layout, cfg=config)
    outputs["paths"].update({f"rq2_{name}": path for name, path in rq2["paths"].items()})
    outputs["rq2"] = rq2

    rq3_config = rq3mod.RQ3Config(group_column="checkpoint_t", seed=config.seed, n_resamples=config.n_resamples, alpha=config.alpha)
    rq3 = generate_rq3(
        cl_tensors,
        rq1["excess"],
        layout,
        retention_frame=retention,
        rq2_anchor_level=rq2["anchor_level"],
        cfg=rq3_config,
    )
    outputs["paths"].update({f"rq3_{name}": path for name, path in rq3["paths"].items()})
    outputs["rq3"] = rq3

    rq4 = generate_rq4(ear_comparison, ear_ablations, layout, cfg=config)
    outputs["paths"].update({f"rq4_{name}": path for name, path in rq4["paths"].items()})
    outputs["rq4"] = rq4
    return outputs


